[ExtensionOf(formDataSourceStr(CustTable,CustTable))]
public final class METCustTableExtForm_Extension
{
}

Method.Source:
    /// <summary>
/// 106341-Customber Bank validation for DD
/// </summary>
/// <returns></returns>
public boolean validateWrite() //1
{
    boolean ret = next validateWrite();
    custTable custTable= this.cursor();
    CustBankAccount bankaccSetup;
    CustBankAccount CustBankAccount =CustBankAccount::find(custTable.AccountNum,custTable.BankAccount);
    select firstonly bankaccsetup where bankaccSetup.CustAccount==custTable.AccountNum
    && bankaccSetup.AccountNum && bankaccSetup.RegistrationNum;
    if(bankaccSetup)
    {
        if(custTable.PaymMode ==METConstants::DD && !custTable.BankAccount)
        {
            ret = false;
            checkFailed("@MET:METCustValidation4");
        }
        if(custTable.BankAccount && !custTable.bankAccountNum())
        {
            ret = false;
            checkFailed("@MET:METCustValidation5");
        }
        if(custTable.BankAccount && !CustBankAccount.RegistrationNum)
        {
            ret = false;
            CustTable.BankAccount = '';
            CustTable.PaymMode = '';
            checkFailed(strFmt("@MET:METCustValidation1",custTable.BankAccount));
        }
    }
    else if(!bankaccSetup &&!custTable.BankAccount&& custTable.PaymMode ==METConstants::DD )
    {
        CustTable.PaymMode = '';
        warning("@MET:METCustValidation2");
    }
    else if(!bankaccSetup && custTable.BankAccount&& custTable.PaymMode ==METConstants::DD )
    {
        custTable.BankAccount='';
        CustTable.PaymMode =  '';
        warning("@MET:METCustValidation3");
    }
    return ret;
}
